import json
import re
from typing import Dict, Any

def parse_key_value_pairs(text: str) -> Dict[str, Any]:
    """
    Filtra e extrai pares chave-valor de um texto estruturado informalmente.
    Suporta formatos como 'chave: valor', 'chave = valor' ou 'chave -> valor'.
    Tenta converter valores numéricos para int ou float automaticamente.
    """
    result = {}
    if not text.strip():
        return result

    # Expressão regular para capturar chave e valor com diferentes delimitadores
    pattern = re.compile(r'^\s*([\w\-]+)\s*(?::|=|->)\s*(.+?)\s*$', re.MULTILINE)

    for match in pattern.finditer(text):
        key, value = match.groups()

        # Tenta converter para número se aplicável
        if value.lower() == 'true':
            parsed_value = True
        elif value.lower() == 'false':
            parsed_value = False
        elif value.lower() == 'none' or value.lower() == 'null':
            parsed_value = None
        else:
            try:
                if '.' in value:
                    parsed_value = float(value)
                else:
                    parsed_value = int(value)
            except ValueError:
                # Remove aspas se o valor for uma string delimitada
                if (value.startswith('"') and value.endswith('"')) or (value.startswith("'") and value.endswith("'")):
                    parsed_value = value[1:-1]
                else:
                    parsed_value = value

        result[key] = parsed_value

    return result

testes:
assert parse_key_value_pairs("") == {}
assert parse_key_value_pairs("   
  	 ") == {}
assert parse_key_value_pairs("status: ativo") == {"status": "ativo"}
assert parse_key_value_pairs("status: ativo
idade = 30
score -> 9.5
verificado: True") == {"status": "ativo", "idade": 30, "score": 9.5, "verificado": True}
assert parse_key_value_pairs("nome: "Ana Maria"
ignore_linha_invalida
conexao -> null") == {"nome": "Ana Maria", "conexao": None}

