def parse_key_value_pairs(text: str) -> dict[str, str]:
    """
    Realiza o parsing de um texto estruturado contendo linhas no formato 'chave=valor'.
    Ignora linhas vazias, linhas que não contêm '=' e remove espaços em branco extras.
    """
    result = {}
    if not text:
        return result

    for line in text.splitlines():
        line = line.strip()
        if not line or "=" not in line:
            continue
        key, val = line.split("=", 1)
        result[key.strip()] = val.strip()

    return result

testes:
assert parse_key_value_pairs("") == {}
assert parse_key_value_pairs("so_chave") == {}
assert parse_key_value_pairs("status=ativo") == {"status": "ativo"}
assert parse_key_value_pairs("   timeout = 30   ") == {"timeout": "30"}
assert parse_key_value_pairs("timeout=30\n\n#comentario\nstatus=ativo\ninvalido") == {"timeout": "30", "status": "ativo"}
assert parse_key_value_pairs("url=https://site.com?param=1") == {"url": "https://site.com?param=1"}

