import json
import re
from typing import Dict, Any, List

def parse_nested_custom_tags(text: str) -> Dict[str, Any]:
    """
    Faz o parsing de um texto contendo tags personalizadas aninhadas em formato pseudo-XML
    e retorna um dicionário estruturado. Converte valores numéricos automaticamente.
    """
    # Regex para identificar tags de abertura e fechamento
    tag_pattern = re.compile(r'<(\w+)>(.*?)</\1>', re.DOTALL)

    def parse_value(val: str) -> Any:
        val = val.strip()
        # Tenta converter para inteiro
        if re.match(r'^-?\d+$', val):
            return int(val)
        # Tenta converter para float
        if re.match(r'^-?\d+\.\d+$', val):
            return float(val)
        # Tenta converter booleanos
        if val.lower() == 'true':
            return True
        if val.lower() == 'false':
            return False
        return val

    def helper(content: str) -> Any:
        content = content.strip()
        matches = list(tag_pattern.finditer(content))

        if not matches:
            return parse_value(content) if content else None

        result: Dict[str, Any] = {}
        for match in matches:
            tag, inner_content = match.groups()
            parsed_inner = helper(inner_content)

            # Trata chaves duplicadas criando uma lista
            if tag in result:
                if isinstance(result[tag], list):
                    result[tag].append(parsed_inner)
                else:
                    result[tag] = [result[tag], parsed_inner]
            else:
                result[tag] = parsed_inner

        return result

    return helper(text) or {}

testes:
assert parse_nested_custom_tags("") == {}
assert parse_nested_custom_tags("<item>value</item>") == {"item": "value"}
assert parse_nested_custom_tags("<data><id>123</id><active>true</active><ratio>4.5</ratio></data>") == {"data": {"id": 123, "active": True, "ratio": 4.5}}
assert parse_nested_custom_tags("<user><name>Alice</name><role>admin</role><role>user</role></user>") == {"user": {"name": "Alice", "role": ["admin", "user"]}}
assert parse_nested_custom_tags("<config><empty></empty></config>") == {"config": {"empty": None}}

