import json
import re
from typing import Dict, Any

def parse_custom_log_to_json(log_line: str) -> Dict[str, Any]:
    """
    Parses a custom log line into a structured dictionary.
    Format: [TIMESTAMP] LEVEL - SERVICE: "MESSAGE" {METADATA_JSON}

    If the line is empty or invalid, returns an empty dictionary.
    """
    if not log_line or not log_line.strip():
        return {}

    pattern = r'^\[([^\]]+)\]\s+([A-Z]+)\s+-\s+([^:]+):\s+"([^"]*)"\s*(.*)$'
    match = re.match(pattern, log_line.strip())

    if not match:
        return {}

    timestamp, level, service, message, raw_metadata = match.groups()

    metadata = {}
    if raw_metadata.strip():
        try:
            metadata = json.loads(raw_metadata.strip())
        except json.JSONDecodeError:
            pass

    return {
        "timestamp": timestamp,
        "level": level,
        "service": service,
        "message": message,
        "metadata": metadata
    }

testes:
assert parse_custom_log_to_json("") == {}
assert parse_custom_log_to_json("   ") == {}
assert parse_custom_log_to_json("[2026-07-19] INFO - AuthService: \"User logged in\" {\"user_id\": 42}") == {"timestamp": "2026-07-19", "level": "INFO", "service": "AuthService", "message": "User logged in", "metadata": {"user_id": 42}}
assert parse_custom_log_to_json("[2026-07-19] WARN - DB: \"Timeout\"") == {"timestamp": "2026-07-19", "level": "WARN", "service": "DB", "message": "Timeout", "metadata": {}}
assert parse_custom_log_to_json("[2026-07-19] ERROR - API: \"Failed\" {invalid_json}") == {"timestamp": "2026-07-19", "level": "ERROR", "service": "API", "message": "Failed", "metadata": {}}
assert parse_custom_log_to_json("Invalid log format") == {}

