import json
import re
from typing import Dict, Any

def parse_custom_kv_format(text: str) -> Dict[str, Any]:
    """
    Realiza o parsing de uma string de texto contendo pares chave-valor customizados.
    O formato aceito é 'chave: "valor"' ou 'chave: valor', separados por vírgula ou quebra de linha.
    Suporta a conversão automática para tipos básicos (int, float, bool, None/null).
    Valores nulos ou vazios são ignorados ou tratados adequadamente.
    """
    result = {}
    if not text or not text.strip():
        return result

    # Expressão regular para capturar chave: valor (lidando com aspas opcionais)
    pattern = re.compile(r'([\w\-]+)\s*:\s*("(.*?)"|([^,\n]+))')

    for match in pattern.finditer(text):
        key = match.group(1)
        # Se houver aspas, pegamos o grupo 3 (dentro das aspas), senão o grupo 4
        val = match.group(3) if match.group(2).startswith('"') else match.group(4).strip()

        if val is None:
            continue

        # Tenta converter para tipos nativos
        val_lower = val.lower()
        if val_lower == 'true':
            result[key] = True
        elif val_lower == 'false':
            result[key] = False
        elif val_lower in ('none', 'null'):
            result[key] = None
        else:
            try:
                if '.' in val:
                    result[key] = float(val)
                else:
                    result[key] = int(val)
            except ValueError:
                result[key] = val

    return result

testes:
assert parse_custom_kv_format("") == {}
assert parse_custom_kv_format("   ") == {}
assert parse_custom_kv_format("status: \"active\"") == {"status": "active"}
assert parse_custom_kv_format("id: 101, status: \"active\", active: True, score: 9.5, metadata: null") == {"id": 101, "status": "active", "active": True, "score": 9.5, "metadata": None}

