import re
from typing import Dict, List, Union

def parse_kv_pairs(text: str) -> Dict[str, Union[str, List[str]]]:
    if not text or not text.strip():
        return {}

    result = {}
    pattern = re.compile(r"(\w+)\s*=\s*(?:\[([^\]]*)\]|([^;]+))")

    for match in pattern.finditer(text):
        key, list_content, scalar_content = match.groups()
        if list_content is not None:
            result[key] = [item.strip() for item in list_content.split(",") if item.strip()]
        else:
            result[key] = scalar_content.strip()

    return result

